// Bring each waiting record together with whatever the consent register says about its subject.
// The join is done here rather than in SQL on purpose: the register is very often a DIFFERENT
// system from the document store, so a template that assumed one JOIN-able database would not
// survive first contact with a real setup.
// This node sits AFTER the register read, so $input.all() is the REGISTER, and the waiting
// records have to be pulled back by name. Getting that the wrong way round costs nothing at
// import time and silently empties the queue at run time.
const register = $input.all().map(i => i.json).filter(r => r && r.subject_id);

const bySubject = {};
for (const r of register) bySubject[String(r.subject_id).trim()] = r;

const out = [];
for (const item of $('Read The Records Waiting To Be Indexed').all()) {
  const d = item.json || {};
  if (d.document_id === undefined || d.document_id === null) continue;   // the alwaysOutputData shim
  const subject = String(d.subject_id === null || d.subject_id === undefined ? '' : d.subject_id).trim();
  const c = subject ? bySubject[subject] : null;
  out.push({ json: {
    document_id: d.document_id,
    subject_id: subject || null,
    title: d.title,
    text: d.text,
    has_consent_row: !!c,
    purposes: c ? c.purposes : null,
    given_at: c ? c.given_at : null,
    withdrawn_at: c ? c.withdrawn_at : null,
    retention_until: c ? c.retention_until : null,
    objected_to_profiling: c ? c.objected_to_profiling : null,
    special_category: c ? c.special_category : null,
  } });
}
return out;

// ONE decision per record. Six refusal grounds, each INDEPENDENT of the others, plus a third
// answer that is neither yes nor no.
//
// The reason this is not a single boolean: a record can fail exactly one ground while passing all
// the rest, so collapsing them loses the only thing the reader needs - WHICH rule stopped it. The
// refusal ground is what a data protection officer is asked for months later, not the fact of the
// refusal.
//
// "held" is deliberately not "refused". A consent row missing the fields the decision needs cannot
// be judged in either direction, and guessing is the failure this whole template exists to stop.
const policy = $('Consent Rules').first().json;
const purpose = String(policy.required_purpose || 'ai_training').trim().toLowerCase();
const listOf = (v) => String(v || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);

const today = new Date();
today.setUTCHours(0, 0, 0, 0);
const asDate = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return isNaN(d.getTime()) ? null : d;
};
const truthy = (v) => v === true || v === 1 || ['true', 'yes', 't', '1'].includes(String(v).trim().toLowerCase());

const rows = $input.all().map(i => i.json).filter(r => r && r.document_id !== undefined);
const out = [];

for (const r of rows) {
  const base = {
    document_id: r.document_id,
    subject_id: r.subject_id || null,
    title: r.title || null,
    text: r.text || null,
    // every key on every branch, so all four outcomes have the same shape (error A21)
    decision: null, ground: null, detail: null,
  };
  const emit = (decision, ground, detail) =>
    out.push({ json: Object.assign({}, base, { decision: decision, ground: ground, detail: detail }) });

  const subject = String(r.subject_id || '').trim();

  // A record about nobody has no consent question to answer. This is the ONLY route to the index
  // that does not require a register entry.
  if (!subject) { emit('eligible', 'not_personal', 'No data subject is attached to this record.'); continue; }

  if (!r.has_consent_row) {
    emit('refused', 'no_consent_record', 'Nothing in the consent register for ' + subject + '.'); continue;
  }

  // UNDECIDABLE, before any refusal ground is tested: if the register row cannot answer the
  // question, no ground below can be trusted either.
  const missing = [];
  if (!r.purposes) missing.push('purposes');
  if (!r.retention_until) missing.push('retention_until');
  if (!r.given_at) missing.push('given_at');
  if (missing.length) {
    emit('held', 'incomplete_record',
         'The consent register entry for ' + subject + ' is missing: ' + missing.join(', ') + '.'); continue;
  }

  // ground 1 - special category (GDPR Article 9). A HARD refusal: there is no policy setting that
  // turns this into a warning, which is the point of putting it first.
  if (truthy(r.special_category)) {
    emit('refused', 'special_category',
         'Marked special category, which needs its own Article 9 condition, not ordinary consent.'); continue;
  }

  // ground 2 - consent withdrawn. Withdrawal is not retroactive to the past, but it absolutely
  // stops anything NEW being indexed from now on.
  const withdrawn = asDate(r.withdrawn_at);
  if (withdrawn && withdrawn <= today) {
    emit('refused', 'consent_withdrawn', 'Consent was withdrawn on ' + String(r.withdrawn_at).slice(0, 10) + '.');
    continue;
  }

  // ground 3 - objection to profiling (Article 21). Independent of consent: a person can consent
  // to a purpose and still object to being profiled for it.
  if (truthy(r.objected_to_profiling)) {
    emit('refused', 'objection_to_profiling', 'This subject has objected to profiling.'); continue;
  }

  // ground 4 - retention. Consent that was once valid does not survive its own retention window.
  const until = asDate(r.retention_until);
  if (until && until < today) {
    emit('refused', 'retention_expired',
         'Retention ran out on ' + String(r.retention_until).slice(0, 10) + '.'); continue;
  }

  // ground 5 - purpose limitation (Article 5(1)(b)). The one almost every pipeline gets wrong:
  // consent for support or marketing is NOT consent to be embedded into a model index.
  const have = listOf(r.purposes);
  if (!have.includes(purpose)) {
    emit('refused', 'purpose_limitation',
         'Consent covers ' + have.join(', ') + ' but not ' + purpose + '.'); continue;
  }

  emit('eligible', 'consent_on_file', 'Consent covers ' + purpose + ' and is inside its retention window.');
}

// A Merge never fires when NONE of its inputs ran, and on template C that produced a run which
// reported absolutely nothing. An empty queue is a real answer and gets its own labelled row.
if (!out.length) {
  out.push({ json: { document_id: null, subject_id: null, title: null, text: null,
                     decision: 'none', ground: 'queue_empty',
                     detail: 'No records were waiting to be indexed.' } });
}
return out;

// What this run decided, counted once. Reads the merged stream rather than any single branch, so
// one index run produces exactly one message no matter how many outcomes occurred.
const policy = $('Consent Rules').first().json;
const maxRows = Number(policy.max_rows_in_report) || 15;

const rows = $input.all().map(i => i.json).filter(r => r && r.decision);
const eligible = rows.filter(r => r.decision === 'eligible');
const refused = rows.filter(r => r.decision === 'refused');
const held = rows.filter(r => r.decision === 'held');
const idle = rows.filter(r => r.decision === 'none');

// Grouping by GROUND is the useful shape: "9 refused" tells a reader nothing, "7 refused for
// purpose limitation" tells them their consent copy is wrong.
const byGround = {};
for (const r of refused.concat(held)) {
  const g = r.ground || 'unknown';
  byGround[g] = (byGround[g] || 0) + 1;
}
const groundLines = Object.keys(byGround).sort()
  .map(g => '- ' + g.replace(/_/g, ' ') + ': ' + byGround[g]);

const examples = refused.concat(held).slice(0, maxRows)
  .map(r => '- ' + (r.title || 'record ' + r.document_id) + ' (' + r.ground.replace(/_/g, ' ') + ')');

const considered = eligible.length + refused.length + held.length;

return [{ json: {
  records_considered: considered,
  embedded: eligible.length,
  refused: refused.length,
  held_for_review: held.length,
  refusal_grounds: byGround,
  queue_was_empty: idle.length > 0 && considered === 0,
  needs_telling: refused.length > 0 || held.length > 0,
  report_text: considered === 0
    ? 'Nothing was waiting to be indexed.'
    : eligible.length + ' of ' + considered + ' record(s) were embedded. '
      + refused.length + ' refused, ' + held.length + ' held for a human.'
      + (groundLines.length ? '\nWhy:\n' + groundLines.join('\n') : '')
      + (examples.length ? '\n' + examples.join('\n') : '')
      + (refused.length + held.length > maxRows
         ? '\n...and ' + (refused.length + held.length - maxRows) + ' more in the manifest.' : ''),
} }];
